qss:
QWidget {
    background: #f3f5f8;
    color: #17202b;
    font-family: "Segoe UI", "Inter", sans-serif;
    font-size: 10pt;
}
QMainWindow {
    background: #eef2f7;
}
QLabel {
    background: transparent;
}
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface {
    background: #ffffff;
    border: 1px solid #d8dee9;
    border-radius: 16px;
}
QLabel#TitleLabel {
    font-size: 16pt;
    font-weight: 700;
    color: #0f172a;
}
QLabel#SubtleLabel {
    color: #64748b;
}
QPushButton {
    background: #e2e8f0;
    color: #0f172a;
    border: 1px solid #cbd5e1;
    border-radius: 12px;
    padding: 8px 12px;
}
QPushButton:hover {
    background: #d9e2ec;
}
QPushButton:pressed {
    background: #ccd7e5;
}
QPushButton#AccentButton {
    background: #2563eb;
    border: 1px solid #2563eb;
    color: #ffffff;
    font-weight: 700;
}
QPushButton#AccentButton:hover {
    background: #2d6ff5;
}
QPushButton#DangerButton {
    background: #fee2e2;
    border: 1px solid #fecaca;
}
QPushButton#DangerButton:hover {
    background: #fecaca;
}
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser {
    background: #ffffff;
    color: #0f172a;
    border: 1px solid #d1d9e6;
    border-radius: 12px;
    padding: 8px;
}
QListWidget::item {
    border-radius: 10px;
    padding: 8px;
    margin: 2px;
}
QListWidget::item:selected {
    background: #dbeafe;
    border: 1px solid #93c5fd;
}
QScrollArea {
    border: none;
    background: transparent;
}
QScrollBar:vertical {
    background: #f1f5f9;
    width: 16px;
    margin: 2px;
    border-radius: 6px;
}
QScrollBar::handle:vertical {
    background: #cbd5e1;
    min-height: 36px;
    border-radius: 7px;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QScrollBar:horizontal { background: #f1f5f9; height: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:horizontal { background: #cbd5e1; min-width: 36px; border-radius: 7px; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0px; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: transparent; }
QCheckBox {
    spacing: 8px;
}
QDialog {
    background: #f3f5f8;
}
QProgressBar {
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    background: #ffffff;
    text-align: center;
    min-height: 18px;
}
QProgressBar::chunk {
    background: #2563eb;
    border-radius: 8px;
}

QFrame#AssistantBubbleCard { background: #ffffff; border: 1px solid #93c5fd; border-left: 4px solid #2563eb; border-radius: 16px; }
QFrame#UserBubbleCard { background: #dbeafe; border: 1px solid #93c5fd; border-radius: 16px; }
